24	import static org.assertj.core.api.Assertions.assertThat;
25	import static org.assertj.core.api.Assertions.assertThatThrownBy;
26	
27	/**
28	 * 轧辊寿命台账：上机、实绩回报、恰达上限禁排、超限拒收、首用标记、
29	 * 同辊同时刻去重、乱序归位复算、幂等/并发、日冻结迟到事件。
30	 */
31	class RollLifeIntegrationTest extends AbstractRollingIntegrationTest {
32	
33	    @Autowired
34	    private RollLifeService rollService;
35	
36	    private RollView mount(String rollNo, String limitKm) {
37	        return rollService.mount(new RollMountRequest("mount-" + rollNo, rollNo,
38	                new BigDecimal(limitKm), T0));
39	    }
40	
41	    private RollActualRequest actual(String requestId, String rollNo, String km, int hour) {
42	        return new RollActualRequest(requestId, rollNo, new BigDecimal(km), T0.plusHours(hour));
43	    }
44	
45	    @Test
46	    void 新辊上机后前5卷带首用标记第6卷起取消() {
47	        mount("R-WARM", "1000");
48	
49	        for (int i = 1; i <= 6; i++) {
50	            RollActualView view = rollService.reportActual(actual("w-" + i, "R-WARM", "1", i));
51	            assertThat(view.accepted()).isTrue();
52	            assertThat(view.firstUse()).as("第 %d 卷首用标记", i).isEqualTo(i <= 5);
53	        }
54	
55	        List<Boolean> flags = jdbc.queryForList(
56	                "SELECT first_use FROM roll_change_actual WHERE roll_no = 'R-WARM'"
57	                        + " ORDER BY recorded_at", Boolean.class);
58	        assertThat(flags).containsExactly(true, true, true, true, true, false);
59	
60	        RollView roll = rollService.get("R-WARM");
61	        assertThat(roll.coilsSinceMount()).isEqualTo(6);
62	        assertThat(roll.totalKm()).isEqualByComparingTo("6");
63	    }
64	
65	    @Test
66	    void 累计里程恰达周期上限即禁排且复算保持结论() {
67	        mount("R-EXACT", "10");
68	
69	        RollActualView first = rollService.reportActual(actual("e-1", "R-EXACT", "6", 1));
70	        assertThat(first.banned()).isFalse();
71	        assertThat(first.remainingKm()).isEqualByComparingTo("4");
72	
73	        RollActualView atLimit = rollService.reportActual(actual("e-2", "R-EXACT", "4", 2));
74	        assertThat(atLimit.accepted()).isTrue();
75	        assertThat(atLimit.totalKm()).isEqualByComparingTo("10");
76	        assertThat(atLimit.remainingKm()).isEqualByComparingTo("0");
77	        assertThat(atLimit.banned()).isTrue();
78	
79	        RollView roll = rollService.get("R-EXACT");
80	        assertThat(roll.status()).isEqualTo("BANNED");
81	
82	        // 恰达上限后任何正里程实绩都超限，不得入库。
83	        assertThatThrownBy(() -> rollService.reportActual(actual("e-3", "R-EXACT", "0.5", 3)))
84	                .isInstanceOf(BusinessException.class)
85	                .hasMessageContaining("超限实绩不得入库");
86	        assertThat(jdbc.queryForObject(
87	                "SELECT COUNT(1) FROM roll_change_actual WHERE roll_no = 'R-EXACT'",
88	                Integer.class)).isEqualTo(2);
89	
90	        // 复算后里程与禁排结论保持。
91	        RollView recomputed = rollService.recompute("R-EXACT");
92	        assertThat(recomputed.totalKm()).isEqualByComparingTo("10");
93	        assertThat(recomputed.status()).isEqualTo("BANNED");
94	    }
95	
96	    @Test
97	    void 超限实绩拒绝入库且里程不变() {
98	        mount("R-OVER", "10");
99	        rollService.reportActual(actual("ov-1", "R-OVER", "6", 1));
100	
101	        assertThatThrownBy(() -> rollService.reportActual(actual("ov-2", "R-OVER", "5", 2)))
102	                .isInstanceOf(BusinessException.class)
103	                .hasMessageContaining("超过周期上限")
104	                .hasMessageContaining("剩余里程 4");
105	
106	        assertThat(jdbc.queryForObject(
107	                "SELECT COUNT(1) FROM roll_change_actual WHERE roll_no = 'R-OVER'",
108	                Integer.class)).isEqualTo(1);
109	        RollView roll = rollService.get("R-OVER");
110	        assertThat(roll.totalKm()).isEqualByComparingTo("6");
111	        assertThat(roll.status()).isEqualTo("IN_SERVICE");
