    /**
     * 同一物理辊同一旧代次是否存在检验中的申请（终止后允许另提新申请）。
     */
    public boolean existsOpenApplication(String physicalNo, int oldGenerationNo) {
        Integer count = jdbc.queryForObject("""
                SELECT COUNT(1) FROM rework_application
                WHERE physical_no = ? AND old_generation_no = ? AND status = 'INSPECTING'
                """, Integer.class, physicalNo, oldGenerationNo);
        return count != null && count > 0;
